//! Oracle tier: reads Goldmark artifacts regenerated by
//! `scripts/regen-fixtures.py` (see docs/FIXTURES.md).
#![cfg(feature = "oracle-fixtures")]
#[path = "support/code_block.rs"]
mod code_block_support;
#[path = "support/html_block.rs"]
mod html_block_support;
#[path = "support/inline.rs"]
mod inline_support;
#[path = "support/reference_paragraph.rs"]
mod reference_paragraph_support;
#[path = "support/table.rs"]
mod table_support;
// SPDX-License-Identifier: MPL-2.0
use d2_rs_text::markdown::{
    block_reader::BlockReader,
    link::{
        extract_link_references, parse_link_destination, parse_link_reference_definition,
        parse_link_title,
    },
    text::Segment,
};
use serde::Deserialize;
use serde_json::{Value, json};
#[derive(Deserialize)]
#[serde(rename_all = "PascalCase")]
struct Request {
    source: String,
    segments: Vec<Segment>,
    kind: String,
    #[serde(default)]
    alignments: Option<Vec<u8>>,
}
#[derive(Deserialize)]
struct Fixture {
    requests: Vec<Request>,
    results: Vec<Value>,
}
fn hex(bytes: &[u8]) -> String {
    bytes.iter().map(|b| format!("{b:02x}")).collect()
}
fn evaluate(q: &Request) -> Value {
    let source: Vec<_> = (0..q.source.len())
        .step_by(2)
        .map(|i| u8::from_str_radix(&q.source[i..i + 2], 16).unwrap())
        .collect();
    if matches!(
        q.kind.as_str(),
        "setextlife" | "setextempty" | "setextnext" | "setextnextempty"
    ) {
        use d2_rs_text::markdown::{
            context::{Context, NodeKind},
            paragraph::Paragraph,
            reader::Reader,
        };
        let mut c = Context::default();
        let root = c.arena.insert(NodeKind::Document);
        let p = c.arena.insert(NodeKind::Paragraph(Paragraph {
            lines: vec![q.segments[0]],
            blank_previous_lines: true,
        }));
        c.arena.append_child(root, p);
        let mut r = Reader::new(&source);
        r.set_position(1, q.segments[1]);
        let (node, state) = c.open_setext_heading(root, Some(p), &mut r);
        if let Some(n) = node {
            c.arena.append_child(root, n);
            if q.kind != "setextlife" {
                let NodeKind::Paragraph(p) = &mut c.arena.node_mut(p).data else {
                    panic!()
                };
                p.lines.clear();
            }
            if q.kind == "setextnext" || q.kind == "setextnextempty" {
                let next = c.arena.insert(NodeKind::Paragraph(Paragraph {
                    lines: if q.kind == "setextnext" {
                        vec![q.segments[0]]
                    } else {
                        Vec::new()
                    },
                    blank_previous_lines: false,
                }));
                c.arena.append_child(root, next);
            }
            c.close_setext_heading(n, &r);
        }
        let mut nodes = Vec::new();
        let mut child = c.arena.node(root).first;
        while let Some(n) = child {
            let (kind, lines, blank) = match &c.arena.node(n).data {
                NodeKind::Paragraph(p) => ("Paragraph", &p.lines, p.blank_previous_lines),
                NodeKind::Heading {
                    lines,
                    blank_previous_lines,
                    ..
                } => ("Heading", lines, *blank_previous_lines),
                _ => panic!(),
            };
            nodes.push(json!({"kind":kind,"lines":lines,"pos":c.node_position(n),"blank":blank}));
            child = c.arena.node(n).next;
        }
        return json!({"nodes":nodes,"state":state.0,"temporary":c.temporary_paragraph.is_some(),"paragraph_attached":c.arena.node(p).parent.is_some()});
    }
    if q.kind == "atx" {
        use d2_rs_text::markdown::{
            context::{Context, NodeKind},
            reader::Reader,
        };
        let mut c = Context::default();
        let mut r = Reader::new(&source);
        r.set_position(0, q.segments[0]);
        let (line, _) = r.peek_line();
        let offset = line
            .unwrap()
            .bytes()
            .iter()
            .position(|&b| b != b' ' && b != b'\t')
            .unwrap() as isize;
        let (node, state) = c.open_atx_heading(&mut r, offset);
        let mut lines = None;
        let mut level = None;
        if let Some(n) = node {
            let NodeKind::Heading {
                lines: ls,
                level: l,
                ..
            } = &c.arena.node(n).data
            else {
                panic!()
            };
            lines = Some(ls);
            level = Some(l);
        }
        let (line, position) = r.position();
        return json!({"lines":lines,"level":level,"state":state.0,"line":line,"position":position});
    }
    if q.kind == "setextbar" {
        return json!(d2_rs_text::markdown::heading::matches_setext_heading_bar(
            &source
        ));
    }
    if q.kind == "listitem" {
        let (matched, kind) = d2_rs_text::markdown::list::parse_list_item(&source);
        return json!({
            "match": matched,
            "kind": match kind {
                d2_rs_text::markdown::list::ListItemType::NotList => 0,
                d2_rs_text::markdown::list::ListItemType::Bullet => 1,
                d2_rs_text::markdown::list::ListItemType::Ordered => 2,
            },
            "offset": d2_rs_text::markdown::list::calc_list_offset(&source, matched),
        });
    }
    if q.kind == "codeblock" || q.kind == "fenceblock" {
        return code_block_support::evaluate(&source, &q.segments, q.kind == "fenceblock");
    }
    if q.kind == "blockquote" || q.kind == "thematic" {
        use d2_rs_text::markdown::{context::Context, reader::Reader};
        let mut r = Reader::new(&source);
        r.set_position(0, q.segments[0]);
        let mut c = Context::default();
        let (node, state) = if q.kind == "blockquote" {
            c.open_blockquote(&mut r)
        } else {
            c.open_thematic_break(&mut r)
        };
        let (line, position) = r.position();
        let (peek, _) = r.peek_line();
        return json!({"node":node.map(|_|if q.kind=="blockquote"{"Blockquote"}else{"ThematicBreak"}),"state":state.0,"line":line,"position":position,"peek":peek.map(|b|hex(&b.bytes())),"offset":r.line_offset()});
    }
    if q.kind == "htmlblock" {
        return html_block_support::evaluate(&source, &q.segments);
    }
    if q.kind == "tableparagraph" || q.kind == "tableinline" {
        return table_support::evaluate(&source, &q.segments, q.kind == "tableinline");
    }
    if q.kind.starts_with("table") {
        use d2_rs_text::markdown::{
            bytes::Bytes,
            context::{Context, NodeKind},
            table::parse_table_delimiter,
        };
        let source = Bytes::new(&source);
        if q.kind == "tabledelimiter" {
            return json!(parse_table_delimiter(q.segments[0], &source));
        }
        let mut c = Context::default();
        let row = c.parse_table_row(
            q.segments[0],
            q.alignments.as_deref(),
            q.kind == "tablerowheader",
            &source,
        );
        let mut ids = Vec::new();
        let mut cells = Vec::new();
        let mut current = c.arena.node(row).first;
        while let Some(id) = current {
            ids.push(id);
            let NodeKind::TableCell { alignment, lines } = &c.arena.node(id).data else {
                unreachable!()
            };
            cells.push(json!({"alignment":alignment,"pos":c.node_position(id),"lines":lines}));
            current = c.arena.node(id).next;
        }
        let escaped=c.escaped_pipe_cells.as_ref().map(|entries|entries.iter().map(|e|json!({"cell":ids.iter().position(|&id|id==e.cell).unwrap(),"positions":e.positions,"transformed":e.transformed})).collect::<Vec<_>>());
        return json!({"cells":cells,"alignments":q.alignments,"pos":c.node_position(row),"count":c.arena.node(row).child_count,"escaped":escaped,"source":hex(&source.bytes())});
    }
    if q.kind == "refparagraph" || q.kind == "refparagraphmutate" {
        return reference_paragraph_support::evaluate(
            &source,
            &q.segments,
            q.kind == "refparagraphmutate",
        );
    }
    if q.kind.starts_with("inline") {
        return inline_support::evaluate(&source, &q.segments, &q.kind);
    }
    if q.kind == "tagreadopen" || q.kind == "tagreadclose" {
        use d2_rs_text::markdown::tag_matcher::match_tag_reader;
        let mut r = BlockReader::new(&source, Some(&q.segments));
        let saved = r.position();
        let mut events = Vec::new();
        let end = match_tag_reader(q.kind == "tagreadclose", || {
            let value = r.read_rune();
            let (line, pos) = r.position();
            events.push(json!({"rune":value.map_or(0,|(c,_)|c as u32),"size":value.map_or(0,|(_,n)|n),"eof":value.is_none(),"line":line,"position":pos}));
            value
        });
        let before = r.position();
        r.set_position(saved.0, saved.1);
        if let Some(end) = end {
            r.advance(end as isize);
        }
        let (line, pos) = r.position();
        return json!({"end":end,"events":events,"before_line":before.0,"before_position":before.1,"line":line,"position":pos,"source":hex(&r.source().bytes()),"plain_equal":true});
    }
    if q.kind == "tagopen" || q.kind == "tagclose" {
        return json!(
            d2_rs_text::markdown::raw_html::match_tag_prefix(&source, q.kind == "tagclose")
                .map_or(-1, |n| n as isize)
        );
    }
    if q.kind == "autoindex" {
        use d2_rs_text::markdown::autolink::{find_email_index, find_url_index};
        return json!([
            find_email_index(&source).map_or(-1, |v| v as isize),
            find_url_index(&source).map_or(-1, |v| v as isize)
        ]);
    }
    if q.kind == "parse" {
        use d2_rs_text::markdown::{
            arena::NodeId,
            bytes::Bytes,
            context::{Context, NodeKind},
            inline::Text,
            reference::Reference,
        };
        use std::{cell::RefCell, rc::Rc};
        let mut c = Context::default();
        for label in ["x", "a", "strasse"] {
            c.references.add(Rc::new(RefCell::new(Reference {
                label: Some(Bytes::new(label.as_bytes())),
                destination: Some(Bytes::new(b"destination")),
                title: Some(Bytes::new(b"title")),
            })));
        }
        let root = c.arena.insert(NodeKind::Container);
        let mut r = BlockReader::new(&source, Some(&q.segments));
        fn tree(c: &Context, id: NodeId, source: &Bytes) -> Value {
            let n = c.arena.node(id);
            let mut children = Vec::new();
            let mut child = n.first;
            while let Some(id) = child {
                children.push(tree(c, id, source));
                child = c.arena.node(id).next;
            }
            let mut data = json!({"children":children,"count":n.child_count});
            match &n.data {
                NodeKind::Container => data["kind"] = json!("root"),
                NodeKind::CodeSpan => data["kind"] = json!("code"),
                NodeKind::Text(t) => {
                    data["kind"] = json!("text");
                    data["segment"] = json!(t.segment);
                    data["raw"] = json!(t.raw);
                    data["soft"] = json!(t.soft_line_break);
                    data["hard"] = json!(t.hard_line_break);
                }
                NodeKind::LinkLabel(t) => {
                    data["kind"] = json!("label");
                    data["segment"] = json!(t.segment);
                    data["image"] = json!(t.is_image);
                }
                NodeKind::Delimiter(v) => {
                    data["kind"] = json!("delimiter");
                    data["segment"] = json!(v.value.segment);
                    data["length"] = json!(v.value.length);
                    data["char"] = json!(v.value.char);
                }
                NodeKind::Emphasis { level, position } => {
                    data["kind"] = json!("emphasis");
                    data["level"] = json!(level);
                    data["pos"] = json!(position);
                }
                NodeKind::AutoLink(v) => {
                    data["kind"] = json!("auto");
                    data["type"] = json!(v.typ);
                    data["label"] = json!(hex(&c.autolink_label(id, source).bytes()));
                    data["url"] = json!(hex(&c.autolink_url(id, source).bytes()));
                }
                NodeKind::RawHtml { segments } => {
                    data["kind"] = json!("html");
                    data["segments"] = json!(segments);
                }
                NodeKind::Link(v) | NodeKind::Image(v) => {
                    data["kind"] = json!(if matches!(n.data, NodeKind::Link(_)) {
                        "link"
                    } else {
                        "image"
                    });
                    data["destination"] = json!(v.destination.as_ref().map(|v| hex(&v.bytes())));
                    data["title"] = json!(v.title.as_ref().map(|v| hex(&v.bytes())));
                    data["pos"] = json!(v.position);
                    data["reference"] = json!(v.reference.as_ref().map(|r| {
                        let r = r.borrow();
                        json!({"type":r.typ,"value":hex(&r.value)})
                    }));
                }
                _ => panic!("unhandled node"),
            }
            data
        }
        let snap = |c: &Context, r: &BlockReader<'_>| {
            let (line, pos) = r.position();
            json!({"tree":tree(c,root,&r.source()),"line":line,"position":pos})
        };
        let mut rounds = vec![snap(&c, &r)];
        while let (Some(line), seg) = r.peek_line() {
            let saved = r.position();
            let byte = line.bytes().first().copied();
            let n = if matches!(byte, Some(b'[' | b'!' | b']')) {
                c.parse_link(root, &mut r)
            } else if matches!(byte, Some(b'*' | b'_')) {
                c.parse_emphasis(&mut r)
            } else if byte == Some(96) {
                Some(c.parse_code_span(&mut r))
            } else if byte == Some(60) {
                c.parse_autolink(&mut r)
                    .or_else(|| c.parse_raw_html(&mut r))
            } else {
                None
            };
            if let Some(n) = n {
                c.arena.append_child(root, n);
            } else {
                r.set_position(saved.0, saved.1);
                r.advance(1);
                let segment = Segment::new(seg.start, seg.start + 1);
                let previous = c.arena.node(root).last;
                if let Some(previous) = previous
                    && let NodeKind::Text(text) = &mut c.arena.node_mut(previous).data
                    && text.segment.stop == segment.start
                    && !text.soft_line_break
                {
                    text.segment = text.segment.with_stop(segment.stop);
                } else {
                    let n = c.arena.insert(NodeKind::Text(Text::new(segment)));
                    c.arena.append_child(root, n);
                }
            }
            rounds.push(snap(&c, &r));
        }
        c.process_delimiters(None);
        rounds.push(snap(&c, &r));
        c.close_link_block();
        rounds.push(snap(&c, &r));
        return json!(rounds);
    }
    if q.kind == "openclose" {
        use d2_rs_text::markdown::context::{Context, NodeKind};
        let mut c = Context::default();
        let root = c.arena.insert(NodeKind::Container);
        let mut labels = Vec::new();
        let mut r = BlockReader::new(&source, Some(&q.segments));
        let snap = |c: &Context,
                    r: &BlockReader<'_>,
                    labels: &Vec<d2_rs_text::markdown::arena::NodeId>| {
            let mut children = Vec::new();
            let mut n = c.arena.node(root).first;
            while let Some(id) = n {
                let node = c.arena.node(id);
                children.push(match &node.data {
                    NodeKind::LinkLabel(v) => {
                        json!({"kind":"label","segment":v.segment,"image":v.is_image})
                    }
                    NodeKind::Text(v) => json!({"kind":"text","segment":v.segment}),
                    _ => panic!("unexpected child"),
                });
                n = node.next;
            }
            let (line, pos) = r.position();
            json!({"children":children,"attached":labels.iter().map(|&id|c.arena.node(id).parent.is_some()).collect::<Vec<_>>(),"count":c.arena.node(root).child_count,"head":c.link_labels.is_some(),"line":line,"position":pos})
        };
        let mut rounds = vec![snap(&c, &r, &labels)];
        while let (Some(line), _) = r.peek_line() {
            let byte = line.bytes().first().copied();
            if matches!(byte, Some(b'[' | b'!')) {
                if let Some(id) = c.parse_link_open(&mut r) {
                    c.arena.append_child(root, id);
                    labels.push(id);
                } else {
                    r.advance(1);
                }
            } else {
                r.advance(1);
            }
            rounds.push(snap(&c, &r, &labels));
        }
        c.close_link_block();
        rounds.push(snap(&c, &r, &labels));
        c.close_link_block();
        rounds.push(snap(&c, &r, &labels));
        return json!(rounds);
    }
    if q.kind == "bottoms" {
        use d2_rs_text::markdown::{
            arena::NodeId,
            context::{Context, DelimiterBottom},
        };
        let mut c = Context::default();
        let mut rounds = Vec::new();
        let pop = |c: &mut Context| match c.pop_link_bottom() {
            DelimiterBottom::Absent => json!("absent"),
            DelimiterBottom::TypedNil => json!("typed_nil"),
            DelimiterBottom::Node(id) => json!(id),
        };
        for &op in &source {
            match op {
                0..=2 => {
                    c.last_delimiter = if op == 0 {
                        None
                    } else {
                        Some(NodeId(op as usize - 1))
                    };
                    c.push_link_bottom();
                }
                3 => rounds.push(pop(&mut c)),
                4 => c.clear_link_bottoms(),
                _ => unreachable!(),
            }
        }
        for _ in 0..=source.len() {
            rounds.push(pop(&mut c));
        }
        return json!(rounds);
    }
    if q.kind == "labels" {
        use d2_rs_text::markdown::context::Context;
        let mut context = Context::default();
        let ids: Vec<_> = q
            .segments
            .iter()
            .enumerate()
            .map(|(i, &s)| context.new_link_label(s, i % 2 == 1))
            .collect();
        let snap = |c: &Context| {
            json!({"head":c.link_labels,"nodes":ids.iter().map(|&id|{
            let s=c.link_label(id);
            json!({"previous":s.previous,"next":s.next,"first":s.first,"last":s.last,"length":c.link_label_length(Some(id))})
        }).collect::<Vec<_>>()})
        };
        let mut rounds = vec![snap(&context)];
        for &id in &ids {
            context.push_link_label(id);
            rounds.push(snap(&context));
        }
        for i in source {
            context.remove_link_label(ids[i as usize]);
            rounds.push(snap(&context));
        }
        return json!(rounds);
    }
    if q.kind == "registry" {
        use d2_rs_text::markdown::{
            bytes::Bytes,
            link::normalize_reference_label,
            reference::{Reference, References},
        };
        use std::{cell::RefCell, rc::Rc};
        let labels: Vec<_> = source.split(|&b| b == 10).map(Bytes::new).collect();
        let mut keys = Vec::new();
        let refs: Vec<_> = labels
            .iter()
            .enumerate()
            .map(|(i, label)| {
                keys.push(label.bytes().to_vec());
                keys.push(normalize_reference_label(&label.bytes()));
                Rc::new(RefCell::new(Reference {
                    label: Some(label.clone()),
                    destination: Some(Bytes::new(i.to_string().as_bytes())),
                    title: None,
                }))
            })
            .collect();
        let mut context = References::default();
        let snapshot = |context: &References| -> Value {
            json!(keys.iter().map(|key|context.get(key).map(|v|{
                let id=refs.iter().position(|r|Rc::ptr_eq(r,&v)).unwrap();
                let v=v.borrow();
                json!({"id":id,"label":hex(&v.label.as_ref().unwrap().bytes()),"destination":hex(&v.destination.as_ref().unwrap().bytes())})
            })).collect::<Vec<_>>())
        };
        let mut rounds = Vec::new();
        for r in &refs {
            context.add(r.clone());
            rounds.push(snapshot(&context));
        }
        for label in labels {
            if !label.is_empty() {
                let b = label.bytes()[0] ^ 32;
                label.set(0, b);
            }
        }
        rounds.push(snapshot(&context));
        return json!(rounds);
    }
    if q.kind == "normalize" {
        return json!(hex(&d2_rs_text::markdown::link::normalize_reference_label(
            &source
        )));
    }
    let mut r = BlockReader::new(&source, Some(&q.segments));
    if q.kind == "paragraph" || q.kind == "paragraphclear" {
        use d2_rs_text::markdown::{
            context::{Context, NodeKind},
            paragraph::BlockState,
        };
        let mut c = Context::default();
        let root = c.arena.insert(NodeKind::Container);
        let (node, state) = c.open_paragraph(&mut r);
        if let Some(node) = node {
            c.arena.append_child(root, node);
        }
        let snap = |c: &Context, r: &BlockReader<'_>, state: BlockState| {
            let lines = node.map(|id| {
                let NodeKind::Paragraph(p) = &c.arena.node(id).data else {
                    unreachable!()
                };
                p.lines.clone()
            });
            let (line, pos) = r.position();
            json!({"state":state.0,"lines":lines,"attached":node.is_some_and(|id|c.arena.node(id).parent.is_some()),"node_pos":node.map_or(-1,|id|c.node_position(id)),"count":c.arena.node(root).child_count,"line":line,"position":pos,"source":hex(&r.source().bytes())})
        };
        let mut rounds = vec![snap(&c, &r, state)];
        if let Some(node) = node {
            loop {
                r.advance_line();
                let state = c.continue_paragraph(node, &mut r);
                rounds.push(snap(&c, &r, state));
                if state == BlockState::CLOSE {
                    break;
                }
            }
            if q.kind == "paragraphclear" {
                let NodeKind::Paragraph(p) = &mut c.arena.node_mut(node).data else {
                    unreachable!()
                };
                p.lines.clear();
            }
            c.close_paragraph(node, &r);
            rounds.push(snap(&c, &r, BlockState(0)));
        }
        return json!(rounds);
    }
    if q.kind == "rawdelimited" || q.kind == "rawtag" {
        use d2_rs_text::markdown::context::{Context, NodeKind};
        let mut c = Context::default();
        let node = if q.kind == "rawtag" {
            c.parse_raw_html(&mut r)
        } else {
            c.parse_raw_html_delimited(&mut r)
        };
        let value = node.map(|id| {
            let NodeKind::RawHtml { segments } = &c.arena.node(id).data else {
                unreachable!()
            };
            segments.clone()
        });
        let (line, pos) = r.position();
        return json!({"segments":value,"line":line,"position":pos,"source":hex(&r.source().bytes())});
    }
    if q.kind == "extract" {
        let source = d2_rs_text::markdown::bytes::Bytes::new(&source);
        let mut lines = q.segments.clone();
        let refs = extract_link_references(source.clone(), &mut lines, true);
        let refs:Vec<_>=refs.into_iter().map(|r|json!({"label":hex(&r.definition.label),"destination":hex(&r.definition.destination.bytes()),"title":r.definition.title.map(|v|hex(&v)),"lines":r.lines,"blank":r.blank_previous_lines})).collect();
        return json!({"references":refs,"remaining":lines,"removed":lines.is_empty(),"source":hex(&source.bytes())});
    }
    if q.kind == "reference" {
        let (reference, start, end) = parse_link_reference_definition(&mut r);
        let reference=reference.map(|v| json!({"label":hex(&v.label),"destination":hex(&v.destination.bytes()),"title":v.title.map(|v|hex(&v)),"first_segment":v.first_segment}));
        let (line, pos) = r.position();
        return json!({"reference":reference,"start":start,"end":end,"line":line,"position":pos,"source":hex(&r.source().bytes()),"peek":r.peek()});
    }
    let (value, ok) = if q.kind == "title" {
        let (v, ok) = parse_link_title(&mut r);
        (v.map(|v| hex(&v)), ok)
    } else {
        let (v, ok) = parse_link_destination(&mut r);
        (v.map(|v| hex(&v.bytes())), ok)
    };
    let (line, pos) = r.position();
    json!({"value":value,"ok":ok,"line":line,"position":pos,"source":hex(&r.source().bytes()),"peek":r.peek()})
}
#[test]
fn pinned_goldmark_link_values() {
    let f: Fixture =
        serde_json::from_str(d2_rs_testdata::oracle_fixture!("tests/fixtures/link.json")).unwrap();
    assert!(!f.requests.is_empty());
    assert_eq!(f.requests.len(), f.results.len());
    for (i, (q, expected)) in f.requests.iter().zip(f.results).enumerate() {
        let actual =
            std::panic::catch_unwind(|| evaluate(q)).unwrap_or_else(|_| json!({"panic":true}));
        assert_eq!(actual, expected, "case {i}");
    }
}
